func (b JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridge) Validate() error {
    if !b.NonExecuting || !b.NonAuthorizing { return fmt.Errorf("JEV materialization admission evaluation chain must be non-executing and non-authorizing") }
    if b.Status==jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeUnknown { if b.MissingStage=="" || b.BridgeDigest!="" { return fmt.Errorf("unknown JEV materialization admission evaluation chain is inconsistent") }; return nil }
    if b.Status!=jevExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridgeBound || b.MissingStage!="" || b.BridgeDigest=="" || b.CandidateMaterializationChainBridgeDigest=="" || b.AdmissionEvaluationBridgeDigest=="" || b.CandidateDecision=="" || b.MaterializationStatus=="" || b.AdmissionDecision=="" || b.EvaluationStatus=="" { return fmt.Errorf("incomplete JEV materialization admission evaluation chain") }
    switch b.AdmissionDecision { case "admit": if b.EvaluationStatus!=jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeEvaluationBound || b.EvaluationMode=="" || b.ReverseObservationDigest=="" || b.ReverseObservationSource=="" || b.ReverseObservationEvidenceDigest=="" || b.EvaluationMetricDigest=="" || b.EvaluationMetricSource=="" || b.EvaluationMetricEvidenceDigest=="" { return fmt.Errorf("admitted JEV materialization chain lost evaluation evidence") }; case "hold": if b.EvaluationStatus!=jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeEvaluationHeld || b.EvaluationMode!="" || b.ReverseObservationDigest!="" || b.ReverseObservationSource!="" || b.ReverseObservationEvidenceDigest!="" || b.EvaluationMetricDigest!="" || b.EvaluationMetricSource!="" || b.EvaluationMetricEvidenceDigest!="" { return fmt.Errorf("held JEV materialization chain contains evaluation evidence") }; case "reject": if b.EvaluationStatus!=jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeEvaluationRejected || b.EvaluationMode!="" || b.ReverseObservationDigest!="" || b.ReverseObservationSource!="" || b.ReverseObservationEvidenceDigest!="" || b.EvaluationMetricDigest!="" || b.EvaluationMetricSource!="" || b.EvaluationMetricEvidenceDigest!="" { return fmt.Errorf("rejected JEV materialization chain contains evaluation evidence") }; default: return fmt.Errorf("invalid JEV materialization chain admission decision") }
    if b.CandidateDecision!=jevExternalApplyCapabilityReviewRevisionCandidateReady && b.AdmissionDecision=="admit" { return fmt.Errorf("JEV materialization chain admitted without a ready candidate") }
    expected:=digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridge(b.Status,b.CandidateMaterializationChainBridgeDigest,b.CandidateDecision,b.RevisionProposalDigest,b.MaterializationBridgeDigest,b.AdmissionDecision,b.AdmissionEvaluationBridgeDigest,b.EvaluationStatus)
    if b.BridgeDigest!=expected { return fmt.Errorf("JEV materialization admission evaluation chain digest mismatch") }
    return nil
}

