    output:=JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridge{Status:jevExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridgeBound,CandidateMaterializationChainBridgeDigest:input.CandidateMaterializationChain.BridgeDigest,CandidateDecision:input.CandidateMaterializationChain.CandidateDecision,RevisionProposalDigest:input.CandidateMaterializationChain.RevisionProposalDigest,CandidateDigest:input.AdmissionEvaluation.CandidateDigest,CandidateSource:input.AdmissionEvaluation.CandidateSource,CandidateGateDigest:input.AdmissionEvaluation.CandidateGateDigest,GeneratedCandidateDigest:input.AdmissionEvaluation.GeneratedCandidateDigest,GeneratedCandidateSource:input.AdmissionEvaluation.GeneratedCandidateSource,GenerationInputDigest:input.AdmissionEvaluation.GenerationInputDigest,GenerationEvidenceDigest:input.AdmissionEvaluation.GenerationEvidenceDigest,GeneratorIdentity:input.AdmissionEvaluation.GeneratorIdentity,MaterializationStatus:input.AdmissionEvaluation.MaterializationStatus,MaterializationBridgeDigest:input.AdmissionEvaluation.MaterializationBridgeDigest,AdmissionDecision:input.AdmissionEvaluation.AdmissionDecision,AdmissionStatus:input.AdmissionEvaluation.AdmissionStatus,AdmissionDigest:input.AdmissionEvaluation.AdmissionDigest,AdmissionSource:input.AdmissionEvaluation.AdmissionSource,AdmissionEvidenceDigest:input.AdmissionEvaluation.AdmissionEvidenceDigest,QualityMetricDigest:input.AdmissionEvaluation.QualityMetricDigest,QualityMetricSource:input.AdmissionEvaluation.QualityMetricSource,QualityMetricEvidenceDigest:input.AdmissionEvaluation.QualityMetricEvidenceDigest,ReviewDigest:input.AdmissionEvaluation.ReviewDigest,ReviewSource:input.AdmissionEvaluation.ReviewSource,ReviewEvidenceDigest:input.AdmissionEvaluation.ReviewEvidenceDigest,AdmissionEvaluationBridgeDigest:input.AdmissionEvaluation.BridgeDigest,EvaluationMode:input.AdmissionEvaluation.EvaluationMode,ReverseObservationDigest:input.AdmissionEvaluation.ReverseObservationDigest,ReverseObservationSource:input.AdmissionEvaluation.ReverseObservationSource,ReverseObservationEvidenceDigest:input.AdmissionEvaluation.ReverseObservationEvidenceDigest,EvaluationMetricDigest:input.AdmissionEvaluation.EvaluationMetricDigest,EvaluationMetricSource:input.AdmissionEvaluation.EvaluationMetricSource,EvaluationMetricEvidenceDigest:input.AdmissionEvaluation.EvaluationMetricEvidenceDigest,EvaluationStatus:input.AdmissionEvaluation.EvaluationStatus,NonExecuting:true,NonAuthorizing:true}
    output.BridgeDigest=digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationBridge(output.Status,output.CandidateMaterializationChainBridgeDigest,output.CandidateDecision,output.RevisionProposalDigest,output.MaterializationBridgeDigest,output.AdmissionDecision,output.AdmissionEvaluationBridgeDigest,output.EvaluationStatus)
